export const getGetSetupUrl = () => {




  return `/api/v1/setup`
}

export const getSetup = async ( options?: Parameters<typeof customFetch>[1]): Promise<Setup> => {

  return customFetch<Setup>(getGetSetupUrl(),
  {
    ...options,
    method: 'GET'


  }
);}





export const getGetSetupQueryKey = () => {
    return [
    `/api/v1/setup`
    ] as const;
    }


export const getGetSetupQueryOptions = <TData = Awaited<ReturnType<typeof getSetup>>, TError = ErrorType<unknown>>( options?: { query?:Partial<UseQueryOptions<Awaited<ReturnType<typeof getSetup>>, TError, TData>>, request?: SecondParameter<typeof customFetch>}
) => {

const {query: queryOptions, request: requestOptions} = options ?? {};

  const queryKey =  queryOptions?.queryKey ?? getGetSetupQueryKey();



    const queryFn: QueryFunction<Awaited<ReturnType<typeof getSetup>>> = ({ signal }) => getSetup({ signal, ...requestOptions });





   return  { queryKey, queryFn, ...queryOptions} as UseQueryOptions<Awaited<ReturnType<typeof getSetup>>, TError, TData> & { queryKey: DataTag<QueryKey, TData, TError> }
}

